		description: 'A header component for team profiles, typically including a background image.',
		status: 'general-availability',
		usageGuidelines: [
			'Use TeamProfileHeader to display a banner or background image at the top of a team profile.',
			'Supports custom background images and fallback colors.',
		],
		keywords: ['profile', 'header', 'team', 'banner', 'identity'],
		category: 'media',
		examples: [
			"import React, { useEffect } from 'react';\nimport type { TeamWithImageUrls } from '@atlaskit/teams-client/types/team';\nimport type { TeamsClientUser as User } from '@atlaskit/teams-client/user';\nimport { TeamStoreContainer, useTeamProfileDataState } from '@atlassian/teams';\nimport { selectField, toggleField } from '@atlassian/teams-app-internal-playground/fields';\nimport {\n\tPlayground,\n\ttype PlaygroundConfig,\n} from '@atlassian/teams-app-internal-playground/playground';\nimport { TeamProfileHeader } from '../src';\nconst TEAM_ID = 'example-team';\nconst config = {\n\tfields: [\n\t\tselectField({\n\t\t\tid: 'height',\n\t\t\tlabel: 'Height (px)',\n\t\t\ttype: 'select',\n\t\t\tdefaultValue: '192',\n\t\t\toptions: [\n\t\t\t\t{ label: '100', value: '100' },\n\t\t\t\t{ label: '192', value: '192' },\n\t\t\t\t{ label: '300', value: '300' },\n\t\t\t],\n\t\t}),\n\t\ttoggleField({\n\t\t\tid: 'isEditable',\n\t\t\tlabel: 'Editable',\n\t\t\ttype: 'toggle',\n\t\t\tdefaultValue: false,\n\t\t}),\n\t\ttoggleField({\n\t\t\tid: 'isHeaderDisabled',\n\t\t\tlabel: 'Header disabled (grayscale)',\n\t\t\ttype: 'toggle',\n\t\t\tdefaultValue: false,\n\t\t}),\n\t\ttoggleField({\n\t\t\tid: 'isDeactivated',\n\t\t\tlabel: 'Deactivated',\n\t\t\ttype: 'toggle',\n\t\t\tdefaultValue: false,\n\t\t}),\n\t],\n} satisfies PlaygroundConfig;\nconst exampleTeamData: TeamWithImageUrls = {\n\tid: TEAM_ID,\n\tdisplayName: 'Example team',\n\tdescription: '',\n\tstate: 'ACTIVE',\n\tmembershipSettings: 'OPEN',\n\trestriction: 'NO_RESTRICTION',\n\tlargeAvatarImageUrl: '',\n\tsmallAvatarImageUrl: '',\n\tlargeHeaderImageUrl: '',\n\tsmallHeaderImageUrl: '',\n};\nconst exampleUser: User = { id: 'current-user', fullName: 'Example user' };\n/**\n * Seeds the team sweet-state store with minimal data so that the\n * TeamProfileHeader HOC recognises the team ID and stops showing a spinner.\n */\nfunction SeedTeamStore({ children }: { children: React.ReactNode }) {\n\tconst [, actions] = useTeamProfileDataState();\n\tuseEffect(() => {\n\t\tactions.prefillTeamData(TEAM_ID, exampleTeamData, [], exampleUser);\n\t}, [actions]);\n\treturn <>{children}</>;\n}\nexport default function TeamProfileHeaderExample(): React.JSX.Element {\n\treturn (\n\t\t<Playground config={config}>\n\t\t\t{({ height, isEditable, isHeaderDisabled, isDeactivated }) => (\n\t\t\t\t<TeamStoreContainer scope=\"profile-header-example\">\n\t\t\t\t\t<SeedTeamStore>\n\t\t\t\t\t\t<TeamProfileHeader\n\t\t\t\t\t\t\tid={TEAM_ID}\n\t\t\t\t\t\t\tteamId={TEAM_ID}\n\t\t\t\t\t\t\ttype=\"team\"\n\t\t\t\t\t\t\taddFlag={() => {}}\n\t\t\t\t\t\t\theight={Number(height)}\n\t\t\t\t\t\t\tisEditable={isEditable}\n\t\t\t\t\t\t\tisHeaderDisabled={isHeaderDisabled}\n\t\t\t\t\t\t\tisDeactivated={isDeactivated}\n\t\t\t\t\t\t\tisOrgLoading={false}\n\t\t\t\t\t\t/>\n\t\t\t\t\t</SeedTeamStore>\n\t\t\t\t</TeamStoreContainer>\n\t\t\t)}\n\t\t</Playground>\n\t);\n}",
		],
